   /// @brief Identifiers for types of E57 elements
   enum NodeType
   {
      TypeStructure = 1,        ///< StructureNode class
      TypeVector = 2,           ///< VectorNode class
      TypeCompressedVector = 3, ///< CompressedVectorNode class
