50:       double x = 0.0;
51: 
52:       /// The Y coordinate of the translation (in meters)
53:       double y = 0.0;
54: 
55:       /// The Z coordinate of the translation (in meters)
56:       double z = 0.0;
57: 
58:       bool operator==( const Translation &rhs ) const
59:       {
60:          return ( x == rhs.x ) && ( y == rhs.y ) && ( z == rhs.z );
61:       }
62: 
63:       bool operator!=( const Translation &rhs ) const
64:       {
65:          return !operator==( rhs );
66:       }
67: 
68:       /// @brief Return "no translation".
69:       /// @returns A translation of (0.0, 0.0, 0.0).
70:       static Translation identity()
71:       {
72:          return {};
73:       }
74:    };
