628: 
629:       /*!
630:       @brief Constructor which allocates buffers for all valid fields in the given Data3D header.
631: 
632:       @details
633:       This constructor will also adjust the min/max fields in the data3D pointFields if
634:       we are using floats, and run some validation on the Data3D.
635: 
636:       @param [in] data3D Completed header which indicates the fields we are using
637: 
638:       @throw ::ErrorValueOutOfBounds (n/c)
639:       @throw ::ErrorInvalidNodeType (n/c)
640:       */
641:       explicit Data3DPointsData_t( e57::Data3D &data3D );
