643:       /// @brief Destructor will delete any memory allocated using the Data3DPointsData_t( const
644:       /// e57::Data3D & ) constructor
645:       ~Data3DPointsData_t();
646: 
647:       /// @brief Pointer to a buffer with the X coordinate (in meters) of the point in Cartesian
648:       /// coordinates
649:       COORDTYPE *cartesianX = nullptr;
650: 
651:       /// @brief Pointer to a buffer with the Y coordinate (in meters) of the point in Cartesian
652:       /// coordinates
653:       COORDTYPE *cartesianY = nullptr;
654: 
655:       /// @brief Pointer to a buffer with the Z coordinate (in meters) of the point in Cartesian
656:       /// coordinates
657:       COORDTYPE *cartesianZ = nullptr;
658: 
659:       /// @brief Value = 0 if the point is considered valid, 1 otherwise
660:       int8_t *cartesianInvalidState = nullptr;
661: 
662:       /// @brief Pointer to a buffer with the Point response intensity. Unit is unspecified.
663:       double *intensity = nullptr;
664: 
665:       /// @brief Value = 0 if the intensity is considered valid, 1 otherwise
666:       int8_t *isIntensityInvalid = nullptr;
667: 
668:       /// @brief Pointer to a buffer with the Red color coefficient. Unit is unspecified
669:       uint16_t *colorRed = nullptr;
670:       /// @brief Pointer to a buffer with the Green color coefficient. Unit is unspecified
671:       uint16_t *colorGreen = nullptr;
672:       /// @brief Pointer to a buffer with the Blue color coefficient. Unit is unspecified
673:       uint16_t *colorBlue = nullptr;
674:       /// @brief Value = 0 if the color is considered valid, 1 otherwise
675:       int8_t *isColorInvalid = nullptr;
676: 
677:       /// @brief Pointer to a buffer with the range (in meters) of points in spherical coordinates.
678:       COORDTYPE *sphericalRange = nullptr;
679: 
680:       /// @brief Pointer to a buffer with the Azimuth angle (in radians) of point in spherical
681:       /// coordinates
682:       COORDTYPE *sphericalAzimuth = nullptr;
