#pragma once

/// @file
/// @brief Data structures for E57 Simple API

#include "E57Format.h"
#include "E57SimpleDataExtensions.h"

namespace e57
{
   /// @cond documentNonPublic The following isn't part of the API, and isn't documented.
   class ReaderImpl;
   class WriterImpl;
