126: /// Tool class to read buffer efficiently without multiplying copy operations.
127: ///
128: /// @warning Pointer input is handled by user!
129: class e57::BufferView
130: {
131: public:
132:    /// @param [in] input filled buffer owned by caller
133:    /// @param [in] size size of input
134:    BufferView( const char *input, uint64_t size ) : streamSize_( size ), stream_( input )
135:    {
136:    }
137: 
138:    uint64_t pos() const
139:    {
140:       return cursorStream_;
141:    }
142: 
143:    bool seek( uint64_t offset, int whence )
144:    {
145:       if ( whence == SEEK_CUR )
146:       {
147:          cursorStream_ += offset;
148:       }
149:       else if ( whence == SEEK_SET )
150:       {
151:          cursorStream_ = offset;
152:       }
153:       else if ( whence == SEEK_END )
154:       {
155:          cursorStream_ = streamSize_ - offset;
156:       }
157: 
158:       if ( cursorStream_ > streamSize_ )
159:       {
160:          cursorStream_ = streamSize_;
161:          return false;
162:       }
163: 
164:       return true;
165:    }
166: 
167:    void read( char *buffer, uint64_t count )
168:    {
169:       const uint64_t start = cursorStream_;
170:       for ( uint64_t i = 0; i < count; ++i )
171:       {
172:          buffer[i] = stream_[start + i];
173:          ++cursorStream_;
174:       }
175:    }
176: 
177: private:
178:    const uint64_t streamSize_;
179:    uint64_t cursorStream_ = 0;
180:    const char *stream_;
181: };
